#!/usr/bin/env node
/**
 * Builds the server bundle for metaverse-hub's `pb_world` match: src/server
 * plus the sim, content JSON and Zod, as one ES2017 script that defines the
 * global `PbSim` (and `PB_SIM_VERSION`). Nakama's goja runtime has no
 * TextEncoder, crypto or timers; tests/net/bundle.test.ts checks the output in
 * a bare `node:vm` context.
 *
 * The module body runs lazily, on the first PbSim call, because every Nakama
 * match VM evaluates the whole module (Contract C12).
 *
 *   npm run build:sim                       # dist-sim/pb-sim.js
 *   npm run build:sim -- --out ../metaverse-hub/server/modules/vendor/pb-sim.js
 */
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { build } from 'rolldown';
import { simHash } from './simHash.mjs';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');

export async function buildSimBundle({
  out,
  entry = 'src/server/index.ts',
  name = 'PbSimModule',
} = {}) {
  const version = simHash(root);
  const result = await build({
    input: resolve(root, entry),
    cwd: root,
    write: false,
    platform: 'neutral',
    transform: { target: 'es2017', define: { __PB_SIM_VERSION__: JSON.stringify(version) } },
    output: { format: 'iife', name, minify: false, comments: false },
  });
  const chunk = result.output.find((o) => o.type === 'chunk');
  if (!chunk) throw new Error('no output chunk');
  const code = [
    '// GENERATED by peoples-bitcoin scripts/build-sim-bundle.mjs. Do not edit.',
    `// The People's Bitcoin world sim, version ${version}.`,
    `var PB_SIM_VERSION = ${JSON.stringify(version)};`,
    'var PbSim = (function () {',
    '  var loaded = null;',
    '  function load() {',
    chunk.code.replace(/^/gm, '    '),
    `    return ${name};`,
    '  }',
    '  function mod() {',
    '    if (!loaded) loaded = load();',
    '    return loaded;',
    '  }',
    '  return {',
    '    version: PB_SIM_VERSION,',
    '    createWorldHost: function (opts) { return mod().createWorldHost(opts); },',
    '    benchWorld: function (players, ticks, walkShare, now) { return mod().benchWorld(players, ticks, walkShare, now); },',
    '    constants: function () { var m = mod(); return { PROTOCOL_VERSION: m.PROTOCOL_VERSION, OP: m.OP, SIM_VERSION: m.SIM_VERSION, GAME_ID: m.GAME_ID }; },',
    '  };',
    '})();',
    '',
  ].join('\n');
  if (out) {
    mkdirSync(dirname(resolve(out)), { recursive: true });
    writeFileSync(resolve(out), code);
  }
  return { code, version };
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const i = process.argv.indexOf('--out');
  const out = i >= 0 ? process.argv[i + 1] : resolve(root, 'dist-sim/pb-sim.js');
  const { code, version } = await buildSimBundle({ out });
  console.log(`pb-sim ${version}: ${(code.length / 1024).toFixed(0)} KB → ${out}`);
}
